import java.util.*;
import java.io.*;

public class Main {
    static int n, k;
    static int[] head, to, next;
    static int edgeIdx;
    static int[] parent, order;
    static int[] d, unc;
    static final int INF = 1_000_000_000;
    static final int NEG = -1_000_000_000;

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        n = fs.nextInt();
        k = fs.nextInt();

        if (n == 1) {
            System.out.println(0);
            return;
        }

        head = new int[n];
        Arrays.fill(head, -1);
        to = new int[2 * (n - 1)];
        next = new int[2 * (n - 1)];
        edgeIdx = 0;

        for (int i = 0; i < n - 1; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            add(a, b);
            add(b, a);
        }

        parent = new int[n];
        Arrays.fill(parent, -1);
        order = new int[n];

        int[] stack = new int[n];
        int top = 0;
        stack[top++] = 0;
        parent[0] = -2;

        int ordLen = 0;
        while (top > 0) {
            int v = stack[--top];
            order[ordLen++] = v;

            for (int e = head[v]; e != -1; e = next[e]) {
                int u = to[e];
                if (u == parent[v]) continue;
                parent[u] = v;
                stack[top++] = u;
            }
        }

        d = new int[n];
        unc = new int[n];

        int low = 0, high = n - 1;
        while (low < high) {
            int mid = (low + high) >>> 1;
            if (feasible(mid)) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }

        System.out.println(low);
    }

    static void add(int u, int v) {
        to[edgeIdx] = v;
        next[edgeIdx] = head[u];
        head[u] = edgeIdx++;
    }

    static boolean feasible(int r) {
        Arrays.fill(d, INF);
        Arrays.fill(unc, 0);

        int cnt = 0;

        for (int i = n - 1; i >= 0; i--) {
            int v = order[i];

            if (unc[v] >= 0 && d[v] != INF && d[v] + unc[v] <= r) {
                unc[v] = NEG;
            }

            if (unc[v] == r) {
                cnt++;
                d[v] = 0;
                unc[v] = NEG;
            }

            if (v != 0) {
                int p = parent[v];

                if (d[v] != INF) {
                    int nd = d[v] + 1;
                    if (nd < d[p]) d[p] = nd;
                }

                if (unc[v] >= 0) {
                    int nu = unc[v] + 1;
                    if (nu > unc[p]) unc[p] = nu;
                }
            }
        }

        if (unc[0] >= 0) cnt++;

        return cnt <= k;
    }

    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}
```

